def solve(inputs: dict) -> float:
    # Parse input
    M = inputs['M']
    n = inputs['n']  # exponent
    mod = inputs['mod']

    # Matrix multiplication with modulo
    def matrix_mult(A, B, mod):
        # A and B are 2x2 matrices
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    # Matrix exponentiation using binary exponentiation
    def matrix_power(M, n, mod):
        # Identity matrix
        result = [[1, 0], [0, 1]]
        base = [row[:] for row in M]  # Copy M

        while n > 0:
            if n % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            n //= 2

        return result

    # Compute M^26 mod 135804
    result_matrix = matrix_power(M, n, mod)

    # Sum all entries
    total = sum(sum(row) for row in result_matrix)

    return float(total % mod)

